import 'package:ejadah_mobile/features/profile/presentation/widgets/qr_matrix.dart';
import 'package:flutter_test/flutter_test.dart';

/// The QR encoder, checked against a reference implementation.
///
/// A QR code that does not scan is the same class of defect as a broken image:
/// it looks right until a stranger points a phone at a printed card, which is
/// the one moment the growth loop depends on. So this suite does not test that
/// "a pattern is drawn" — it compares the produced matrix, module for module,
/// against vectors generated by the `qrcode` reference encoder at error
/// correction level L, byte mode, for every mask and every version the app can
/// produce.
void main() {
  group('encoding matches the reference encoder', () {
    for (final entry in _payloads.entries) {
      for (var mask = 0; mask < 8; mask++) {
        test('${entry.key}, mask $mask', () {
          final matrix = QrMatrix.encodeWithMask(entry.value, mask);
          expect(matrix, isNotNull, reason: 'payload must fit versions 1-5');

          final expected = _reference['${entry.key}|$mask']!;
          expect(matrix!.version, expected.version);
          expect(_digest(_flatten(matrix)), expected.digest);
        });
      }
    }
  });

  test('the version grows with the payload, and stops at 5', () {
    // Twelve header bits then eight per byte, so each version holds two
    // fewer bytes than it has data codewords.
    expect(QrMatrix.encode('x' * 17)!.version, 1);
    expect(QrMatrix.encode('x' * 18)!.version, 2);
    expect(QrMatrix.encode('x' * 32)!.version, 2);
    expect(QrMatrix.encode('x' * 33)!.version, 3);
    expect(QrMatrix.encode('x' * 53)!.version, 3);
    expect(QrMatrix.encode('x' * 54)!.version, 4);
    expect(QrMatrix.encode('x' * 78)!.version, 4);
    expect(QrMatrix.encode('x' * 79)!.version, 5);
    expect(QrMatrix.encode('x' * QrMatrix.maxBytes)!.version, 5);
    // Beyond the supported range the encoder says so rather than producing a
    // truncated code; the card screen then shows the link as text.
    expect(QrMatrix.encode('x' * (QrMatrix.maxBytes + 1)), isNull);
    expect(QrMatrix.encode(''), isNull);
  });

  test('a real card URL produces a version-3 code', () {
    final matrix = QrMatrix.encode(
      'https://ejadah.international/dr/nour-hassan',
    )!;
    expect(matrix.version, 3);
    expect(matrix.size, 29);
    expect(matrix.mask, inInclusiveRange(0, 7));
  });

  test('the anchor matrix is drawn exactly', () {
    // A full matrix written out, so a failure is readable rather than a
    // changed hash. Generated by the reference encoder for "A", mask 0.
    final matrix = QrMatrix.encodeWithMask('A', 0)!;
    final rows = [
      for (var y = 0; y < matrix.size; y++)
        [
          for (var x = 0; x < matrix.size; x++) matrix.isDark(x, y) ? '#' : '.',
        ].join(),
    ];
    expect(rows, _anchor);
  });

  test('the function patterns are where the specification puts them', () {
    final matrix = QrMatrix.encode(
      'https://ejadah.international/verify/EJ-DEMO-0001',
    )!;
    final size = matrix.size;

    // The three finder centres are dark, and their separators are light.
    for (final centre in [(3, 3), (size - 4, 3), (3, size - 4)]) {
      expect(matrix.isDark(centre.$1, centre.$2), isTrue);
      // The light ring two modules out from the centre.
      expect(matrix.isDark(centre.$1 + 2, centre.$2), isFalse);
      // And the dark ring beyond it.
      expect(matrix.isDark(centre.$1 - 3, centre.$2), isTrue);
    }

    // The timing patterns alternate.
    for (var i = 8; i < size - 8; i++) {
      expect(matrix.isDark(6, i), i.isEven, reason: 'timing column at $i');
      expect(matrix.isDark(i, 6), i.isEven, reason: 'timing row at $i');
    }

    // The module that is always dark.
    expect(matrix.isDark(8, size - 8), isTrue);
  });

  test('the data codewords carry the payload in byte mode', () {
    final codewords = QrMatrix.debugCodewords('A')!;
    // 0x40 = byte mode, 0x14 0x10 = length 1 then 'A' (0x41) straddling the
    // nibble boundary, then the specified alternating pad bytes.
    expect(codewords.take(3), [0x40, 0x14, 0x10]);
    expect(codewords.skip(3).take(4), [0xEC, 0x11, 0xEC, 0x11]);
    // 19 data codewords plus 7 error-correction codewords at version 1 level L.
    expect(codewords, hasLength(26));
  });
}

const Map<String, String> _payloads = {
  'short': 'A',
  'card': 'https://ejadah.international/dr/nour-hassan',
  'verify': 'https://ejadah.international/verify/EJ-DEMO-0001',
  'longHandle':
      'https://ejadah.international/dr/'
      'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',
  'longCode':
      'https://ejadah.international/verify/'
      'ZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZ',
};

typedef _Vector = ({int version, String digest});

/// FNV-1a digests of the reference matrices, flattened row-major as `0`/`1`.
const Map<String, _Vector> _reference = {
