/// The reference matrix for "A" at mask 0, written out in full.
const List<String> _anchor = [
  '#######..#.##.#######',
  '#.....#..###..#.....#',
  '#.###.#.##.##.#.###.#',
  '#.###.#..#.#..#.###.#',
  '#.###.#...#.#.#.###.#',
  '#.....#.....#.#.....#',
  '#######.#.#.#.#######',
  '........##.##........',
  '###.########.##...#..',
  '#.##....#.....#...##.',
  '.#.####..##.#...#...#',
  '.#.##...##....#...#..',
  '..##.##.#...#.#.#.#.#',
  '........#..#.#.#.#.#.',
  '#######.#.##.###.####',
  '#.....#.######.###...',
  '#.###.#.##.#.###.##.#',
  '#.###.#..##...#...##.',
  '#.###.#.##..#...#...#',
  '#.....#.#.....#...##.',
  '#######.###.#.#.#.###',
];

String _flatten(QrMatrix matrix) {
  final buffer = StringBuffer();
  for (var y = 0; y < matrix.size; y++) {
    for (var x = 0; x < matrix.size; x++) {
      buffer.write(matrix.isDark(x, y) ? '1' : '0');
    }
  }
  return buffer.toString();
}

/// FNV-1a, 64-bit. Chosen so the vectors above stay short and so the test
/// needs no dependency to verify them.
String _digest(String value) {
  var hash = BigInt.parse('cbf29ce484222325', radix: 16);
  final prime = BigInt.parse('100000001b3', radix: 16);
  final mask = (BigInt.one << 64) - BigInt.one;
  for (final unit in value.codeUnits) {
    hash = (hash ^ BigInt.from(unit)) * prime & mask;
  }
  return hash.toRadixString(16).padLeft(16, '0');
}
